const adminDeleteLink = `-- name: AdminDeleteLink :execrows
DELETE FROM links
WHERE id = $1
`

func (q *Queries) AdminDeleteLink(ctx context.Context, id int64) (int64, error) {
	result, err := q.db.Exec(ctx, adminDeleteLink, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
